let colors = ['#083d77', '#38187d', '#d00000', '#ffba08', '#fe4a73', '#08804e', '#42bfdd'];

let ctx;
let centerX, centerY;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;

	let cellCount = 8;
	let w = width / cellCount;
	let hw = w / 2;


	background('#dfdfdf');

	for (let i = 0; i <= cellCount; i++) {
		for (let j = -1; j <= cellCount; j++) {
			let x = i * w + (w / 2);
			let y = j * w + (w / 2);
			let ww = w / 4;
			let a = 0;
			if (i % 2 == 0) a = -PI / 2;
			push();
			translate(x, y);
			noStroke();
			noFill();
			beginShape();
			vertex(-hw - ww, -hw + ww);
			vertex(-hw - ww, -hw - ww);
			vertex(-hw + ww, -hw - ww);
			vertex(-hw + ww, -hw);
			vertex(hw - ww, -hw);
			vertex(hw - ww, -hw + ww);
			vertex(hw, -hw + ww);
			vertex(hw, hw - ww);
			vertex(hw - ww, hw - ww);
			vertex(hw - ww, hw);
			vertex(-hw + ww, hw);
			vertex(-hw + ww, hw - ww);
			vertex(-hw, hw - ww);
			vertex(-hw, -hw + ww);
			endShape(CLOSE);
			pop();
			form(x, y, w, a);
		}
	}
}

function form(x, y, w, a) {
	let type = int(random(6));
	let stClr = '#000';
	shuffle(colors, true);
	push();
	translate(x, y);
	rotate(a);
	if (random() < 0.5) {
		rotate(PI / 2);
		scale(1, -1);
	}
	strokeWeight(w * 0.02);
	if (type == 0) {
		noStroke();
		fill(colors[2]);
		circle(-w / 2, -w / 2, w * 0.4);
		fill(colors[3]);
		arc(-w / 2, -w / 2, w * 0.25, w * 0.25, 0, PI);

		fill(colors[0]);
		beginShape();
		vertex(-w * 0.4, -w * 0.2);
		vertex(-w * 0.2, -w * 0.4);
		vertex(-w * 0, -w * 0.4);
		vertex(-w * 0, w * 0);
		vertex(-w * 0.2, w * 0.2);
		vertex(-w * 0.4, w * 0.2);
		endShape(CLOSE);

		fill(colors[1]);
		circle(-w * 0.3, w * 0.1, w * 0.1);
		circle(-w * 0.1, -w * 0.3, w * 0.1);

		fill(random(colors));
		rect(w * 0.125, -w * 0.2, w * 0.1, w * 0.5);

		fill(random(colors));
		rect(-w * 0.05, w * 0.3, w * 0.2, w * 0.1);

		fill(random(colors));
		circle(w * 0.4, w * 0.15, w * 0.1);
		circle(w * 0.4, 0, w * 0.1);
		circle(w * 0.4, -w * 0.15, w * 0.1);

		stroke(stClr);
		line(w * 0.2, w * 0.4, -w * 0.2, w * 0.4);
		line(w * 0.15, w * 0.45, w * 0.15, w * 0.2);
		line(w * 0.1, w * 0.45, w * 0.1, w * 0.1);

	} else if (type == 1) {
		stroke(stClr);
		line(-w * 0.625, -w * 0.625, -w * 0.1, -w * 0.1);
		line(-w * 0.4, -w * 0.6, -w * 0.6, -w * 0.4);
		noStroke();

		fill(random(colors));
		circle(-w * 0.625, -w * 0.625, w * 0.1);
		circle(-w * 0.1, -w * 0.1, w * 0.1);
		fill(random(colors));
		circle(-w * 0.4, -w * 0.6, w * 0.1);
		circle(-w * 0.6, -w * 0.4, w * 0.1);

		fill(random(colors));
		beginShape();
		vertex(-w * 0.45, w * 0.2);
		vertex(-w * 0.45, -w * 0.3);
		vertex(-w * 0, w * 0.2);
		endShape(CLOSE);

		fill(random(colors));
		circle(-w * 0.1, -w * 0.35, w * 0.2);

		fill(random(colors));
		beginShape();
		vertex(w * 0.05, -w * 0.05);
		vertex(w * 0.05, -w * 0.45);
		vertex(w * 0.2, -w * 0.45);
		vertex(w * 0.2, -w * 0.2);
		vertex(w * 0.4, -w * 0.2);
		vertex(w * 0.4, -w * 0.05);
		endShape(CLOSE);

		fill(random(colors));
		arc(0, w * 0.3, w * 0.3, w * 0.3, 0, PI, PIE);

		fill(random(colors));
		arc(w * 0.25, w * 0.2, w * 0.3, w * 0.3, PI, TAU, PIE);

		stroke(stClr);
		line(-w * 0.2, w * 0.05, w * 0.05, w * 0.05);
		line(-w * 0.2, w * 0.12, w * 0.05, w * 0.12);
	} else if (type == 2) {
		stroke(stClr);
		noFill();
		arc(-w * 0.5, -w * 0.6, w * 0.3, w * 0.3, 0, PI);
		line(-w * 0.2, -w * 0.4, w * 0.15, -w * 0.4);
		line(w * 0.1, -w * 0.45, w * 0.1, -w * 0.2);
		line(w * 0, -w * 0.45, w * 0, -w * 0.2);

		line(w * 0.1, w * 0.4, w * 0.1, 0);
		line(w * 0.1, w * 0.4, w * 0.1, 0);
		arc(w * 0.25, 0, w * 0.3, w * 0.3, PI, TAU + PI / 2);
		line(w * 0.25, w * 0.15, w * 0.25, w * 0);

		guniguni(-w * 0.1, -w * 0.1, -w * 0.1, w * 0.35);

		noStroke();
		fill(random(colors));
		circle(-w * 0.1, -w * 0.15, w * 0.1);
		circle(-w * 0.1, w * 0.4, w * 0.1);

		fill(random(colors));
		circle(-w * 0.2, -w * 0.27, w * 0.15);

		fill(random(colors));
		rect(-w * 0.375, 0, w * 0.15, w * 0.4);

		fill(random(colors));
		rect(-w * 0.375, -w * 0.35, w * 0.15, w * 0.15);

		fill(random(colors));
		circle(-w * 0.65, -w * 0.6, w * 0.1);
		circle(-w * 0.35, -w * 0.6, w * 0.1);
		fill(random(colors));
		circle(w * 0.25, 0, w * 0.1);
	} else if (type == 3) {
		noFill();
		stroke(stClr);
		beginShape();
		vertex(-w * 0.6, -w * 0.35);
		vertex(-w * 0.6, -w * 0.65);
		vertex(-w * 0.5, -w * 0.55);
		vertex(-w * 0.35, -w * 0.55);
		endShape();
		arc(-w * 0.1, -w * 0.1, w * 0.25, w * 0.25, 0, PI);
		arc(-w * 0.35, -w * 0.1, w * 0.25, w * 0.25, 0, PI);
		arc(w * 0.15, -w * 0.1, w * 0.25, w * 0.25, 0, PI);
		rect(0, -w * 0.35, w * 0.35, w * 0.1);
		line(w * 0.4, -w * 0.1, w * 0.4, w * 0.1);
		arc(w * 0.4, w * 0.4, w * 0.5, w * 0.5, PI, PI * 1.5);
		line(-w * 0.4, w * 0.1, -w * 0.4, w * 0.2);
		line(-w * 0.4, w * 0.15, -w * 0.15, w * 0.15);
		arc(-w * 0.15, w * 0.25, w * 0.2, w * 0.2, -PI / 2, PI / 2);

		noStroke();
		fill(random(colors));
		circle(-w * 0.5, -w * 0.55, w * 0.1);

		fill(random(colors));
		circle(-w * 0.4, -w * 0.4, w * 0.1);

		fill(random(colors));
		circle(-w * 0.3, -w * 0.3, w * 0.1);

		fill(random(colors));
		rect(w * 0.15, -w * 0.15, w * 0.15);

		fill(random(colors));
		circle(w * 0.4, w * 0.15, w * 0.1);
		circle(w * 0.4, -w * 0.1, w * 0.1);

		fill(random(colors));
		circle(-w * 0.15, w * 0.29, w * 0.15);

	} else if (type == 4) {
		noStroke();
		fill(random(colors));
		triangle(-w * 0.7, -w * 0.7, -w * 0.3, -w * 0.7, -w * 0.7, -w * 0.4);
		fill(random(colors));
		circle(-w * 0.0, -w * 0.1, w * 0.2);
		fill(colors[0]);
		beginShape();
		vertex(-w * 0.45, -w * 0.1);
		for (let a = PI; a >= PI / 2; a -= (TAU / 360)) {
			vertex(w * 0.175 * cos(a), -w * 0.1 + w * 0.175 * sin(a));
		}
		vertex(-w * 0, w * 0.2);
		vertex(-w * 0.45, w * 0.2);
		endShape();
		fill(colors[1]);
		rect(-w * 0.35, w * 0.05, w * 0.1, w * 0.2);

		fill(random(colors));
		circle(w * 0.3, w * 0, w * 0.35);

		noFill();
		stroke(stClr);
		arc(-w * 0.6, -w * 0.2, w * 0.4, w * 0.4, -PI / 2, 0);
		line(-w * 0.5, -w * 0.3, -w * 0.3, -w * 0.5);
		line(-w * 0.45, -w * 0.25, -w * 0.25, -w * 0.45);
		line(-w * 0.25, -w * 0.35, w * 0.15, -w * 0.35);
		line(w * 0.1, -w * 0.4, w * 0.1, -w * 0.3);
		line(w * 0.05, -w * 0.4, w * 0.05, -w * 0.3);
		arc(w * 0.1, w * 0.35, w * 0.2, w * 0.2, -PI * 0.25, PI);
		arc(-w * 0.1, w * 0.35, w * 0.2, w * 0.2, PI * 0.75, TAU);
		line(w * 0.1, w * 0.2, w * 0.25, w * 0.05);
		line(w * 0.15, w * 0.25, w * 0.3, w * 0.1);
	} else if (type == 5) {
		noFill();
		stroke(stClr);
		line(-w * 0.45, -w * 0.7, -w * 0.3, w * 0.05);
		line(-w * 0.3, -w * 0.7, -w * 0.45, w * 0.05);
		beginShape();
		vertex(-w * 0.2, -w * 0.45);
		vertex(-w * 0.05, -w * 0.3);
		vertex(w * 0.1, -w * 0.45);
		vertex(w * 0.175, -w * 0.375);
		vertex(w * 0.1, -w * 0.3);
		vertex(-w * 0.05, -w * 0.45);
		vertex(-w * 0.2, -w * 0.3);
		endShape();

		line(-w * 0.45, w * 0.2, -w * 0.1, w * 0.2);
		line(-w * 0.2, w * 0.1, -w * 0.2, w * 0.45);
		arc(-w * 0.1, w * 0.1, w * 0.2, w * 0.2, PI, TAU + PI / 2);
		beginShape();
		vertex(w * 0.4, w * 0.15);
		vertex(w * 0.35, w * 0.1);
		vertex(w * 0.3, w * 0.15);
		endShape();

		fill(random(colors));
		arc(-w * 0.55, -w * 0.6, w * 0.2, w * 0.2, PI / 2, PI * 1.5);
		line(-w * 0.55, -w * 0.7, -w * 0.55, -w * 0.3);

		noStroke();
		fill(random(colors));
		square(w * 0.15, -w * 0.1, w * 0.15);
		fill(random(colors));
		square(w * 0.35, -w * 0.1, w * 0.15);
		square(-w * 0.05, -w * 0.1, w * 0.15);
		fill(random(colors));
		circle(w * 0.15, w * 0.15, w * 0.18);
		circle(w * 0.15, w * 0.33, w * 0.12);
		circle(w * 0.15, w * 0.45, w * 0.06);
	}
	pop();
}

function guniguni(x1, y1, x2, y2) {
	let dst = dist(x1, y1, x2, y2);
	let ang = atan2(y2 - y1, x2 - x1);
	let cNum = int(dst * 3);
	let waveNum = 7 * PI;
	let r = dst * 0.15;
	push();
	translate(x1, y1);
	rotate(ang);
	beginShape();
	for (let i = 0; i < cNum; i++) {
		let nrm = norm(i, 0, cNum - 1);
		let amp = r * sin(PI * nrm);
		let yy = lerp(0, amp, sin(nrm * waveNum));
		let xx = lerp(0, dst, nrm);
		vertex(xx, yy);
	}
	endShape();
	pop();
}



